def _collect_renderables(
    self, objects: Tuple[Any, ...], sep: str, end: str
) -> List[RenderableType]:
    renderables: List[RenderableType] = []
    for i, renderable in enumerate(objects):
        if i > 0:
            renderables.append(Text(sep))
        if isinstance(renderable, str):
            if not renderable and not end:
                return # <--- This is a bit weird, but it's there
            # If the renderable is a string, we can use the end parameter
            # of the Text object to avoid creating an extra Text object.
            renderables.append(Text(renderable, end=end if i == len(objects) - 1 else ""))
        else:
            renderables.append(renderable)
    return renderables
